config {
  format = "compact"
}

plugin "terraform" {
  enabled = true
  preset  = "recommended"
}

plugin "aws" {
  enabled = true
  version = "0.38.0"
  source  = "github.com/terraform-linters/tflint-ruleset-aws"
}

terraform {
  # `moved` blocks (shipped by later versions of this module) land in Terraform 1.1.
  required_version = ">= 1.1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }
}

variable "name_prefix" {
  description = "SSM parameter name prefix, without leading slash."
  type        = string
}

variable "config" {
  description = "Application configuration, stored as one JSON SSM parameter."
  type        = map(string)
}

variable "feature_flags" {
  description = "Feature flags, one SSM parameter per flag. Empty by default so consumers can adopt the module for the config parameter first (step 3) and hand over the flags later (step 4)."
  type        = map(string)
  default     = {}
}

terraform {
  # `moved` blocks (shipped by this version) land in Terraform 1.1.
  required_version = ">= 1.1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }
}

variable "name_prefix" {
  description = "SSM parameter name prefix, without leading slash."
  type        = string
}

variable "config" {
  description = "Application configuration, stored as one JSON SSM parameter."
  type        = map(string)
}

variable "feature_flags" {
  description = "Feature flags, one SSM parameter per flag."
  type        = map(string)
  default     = {}
}

terraform {
  # `moved` blocks (shipped by this version) land in Terraform 1.1.
  required_version = ">= 1.1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }
}

variable "name_prefix" {
  description = "SSM parameter name prefix, without leading slash."
  type        = string
}

variable "config" {
  description = "Application configuration, stored as one JSON SSM parameter."
  type        = map(string)
}

variable "feature_flags" {
  description = "Feature flags, one SSM parameter per flag."
  type        = map(string)
  default     = {}
}

# The chain documents the full history of the resource. A consumer coming from
# v1 replays config -> app_config -> this in a single plan; a consumer coming
# from v2 replays only the second hop. This is why a published module KEEPS its
# moved blocks: drop the first hop and every v1 consumer breaks.

moved {
  from = aws_ssm_parameter.config
  to   = aws_ssm_parameter.app_config
}

moved {
  from = aws_ssm_parameter.app_config
  to   = aws_ssm_parameter.this
}

terraform {
  # Feature floors demonstrated in this lab: `moved` 1.1, `import` blocks 1.5,
  # `removed` + destroy=false 1.7.
  required_version = ">= 1.7.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }

  backend "local" {
    path = "terraform.tfstate"
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region."
  type        = string
  default     = "eu-west-1"
}

variable "name_prefix" {
  description = "SSM parameter name prefix, without leading slash."
  type        = string
  default     = "tf-state-refactoring"
}

variable "feature_flags" {
  description = "Feature flags, one SSM parameter per flag."
  type        = map(string)
  default = {
    dark-mode = "off"
    beta-api  = "on"
  }
}

output "config_parameter_name" {
  description = "Name of the app config SSM parameter."
  value       = aws_ssm_parameter.cfg_param_1.name
}

output "feature_flag_names" {
  description = "Names of the feature flag SSM parameters."
  value       = [for p in aws_ssm_parameter.feature_flags : p.name]
}

output "config_parameter_name" {
  description = "Name of the app config SSM parameter."
  value       = aws_ssm_parameter.config.name
}

output "feature_flag_names" {
  description = "Names of the feature flag SSM parameters."
  value       = [for p in aws_ssm_parameter.feature_flags : p.name]
}

output "config_parameter_name" {
  description = "Name of the app config SSM parameter."
  value       = aws_ssm_parameter.app_config.name
}

output "feature_flag_names" {
  description = "Names of the feature flag SSM parameters."
  value       = [for p in aws_ssm_parameter.feature_flags : p.name]
}

output "config_parameter_name" {
  description = "Name of the app config SSM parameter."
  value       = aws_ssm_parameter.this.name
}

output "feature_flag_names" {
  description = "Names of the feature flag SSM parameters."
  value       = [for p in aws_ssm_parameter.feature_flags : p.name]
}

output "config_parameter_name" {
  description = "Name of the app config SSM parameter."
  value       = aws_ssm_parameter.app_config.name
}

output "feature_flag_names" {
  description = "Names of the feature flag SSM parameters."
  value       = [for p in aws_ssm_parameter.feature_flags : p.name]
}

output "config_parameter_name" {
  description = "Name of the app config SSM parameter."
  value       = module.app_config.config_parameter_name
}

output "feature_flag_names" {
  description = "Names of the feature flag SSM parameters."
  value       = [for p in aws_ssm_parameter.feature_flags : p.name]
}

# Step 4 - the split reaches the for_each set: the feature flags move into the
# module. One moved block on the RESOURCE address carries every instance
# ("dark-mode", "beta-api", ...) - no per-key block needed for a 1:1 move.
#
# Prove it:
#   terraform plan   -> one "has moved to" line per flag instance,
#                       Plan: 0 to add, 0 to change, 0 to destroy.

module "app_config" {
  source = "../modules/app-config/v1"

  name_prefix = var.name_prefix
  config = {
    log_level = "info"
    timeout_s = "30"
  }
  feature_flags = var.feature_flags
}

moved {
  from = aws_ssm_parameter.feature_flags
  to   = module.app_config.aws_ssm_parameter.feature_flags
}

resource "aws_ssm_parameter" "billing_export" {
  name  = "/${var.name_prefix}/billing/export-bucket"
  type  = "String"
  value = "s3://example-billing-exports"
}

output "config_parameter_name" {
  description = "Name of the app config SSM parameter."
  value       = module.app_config.config_parameter_name
}

output "feature_flag_names" {
  description = "Names of the feature flag SSM parameters."
  value       = module.app_config.feature_flag_names
}

output "config_parameter_name" {
  description = "Name of the app config SSM parameter."
  value       = module.app_config.config_parameter_name
}

output "feature_flag_names" {
  description = "Names of the feature flag SSM parameters."
  value       = module.app_config.feature_flag_names
}

output "config_parameter_name" {
  description = "Name of the app config SSM parameter."
  value       = module.app_config.config_parameter_name
}

output "feature_flag_names" {
  description = "Names of the feature flag SSM parameters."
  value       = module.app_config.feature_flag_names
}

# Step 6 - handover: the billing parameter never belonged here. `moved` cannot
# cross state files - the workflow that takes over is `removed` (forget without
# destroying) here, then an `import` block in the billing team's root
# (../adjacent). The resource survives the whole trip.
#
# Prove it:
#   terraform plan   -> "will no longer be managed by Terraform, but will not be
#                        destroyed" - Plan: 0 to add, 0 to change, 0 to destroy.
#   terraform apply  -> parameter gone from THIS state, still on AWS.
#   then: cd ../adjacent && terraform init && terraform plan -> "to import"

module "app_config" {
  source = "../modules/app-config/v3"

  name_prefix = var.name_prefix
  config = {
    log_level = "info"
    timeout_s = "30"
  }
  feature_flags = var.feature_flags
}

removed {
  from = aws_ssm_parameter.billing_export

  lifecycle {
    destroy = false
  }
}

output "config_parameter_name" {
  description = "Name of the app config SSM parameter."
  value       = module.app_config.config_parameter_name
}

output "feature_flag_names" {
  description = "Names of the feature flag SSM parameters."
  value       = module.app_config.feature_flag_names
}

terraform {
  # `import` blocks land in Terraform 1.5.
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }

  backend "local" {
    path = "terraform.tfstate"
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region."
  type        = string
  default     = "eu-west-1"
}

variable "name_prefix" {
  description = "SSM parameter name prefix, without leading slash. Must match the value used in ../live."
  type        = string
  default     = "tf-state-refactoring"
}

