206	  /* ====== slide-types: converge / split (§5.7) ======
207	     Flex, jamais grid : `grid-row: 1 / -1` ne s'étend PAS quand les rangées sont implicites
208	     (`-1` vise la dernière ligne EXPLICITE), la cible restait collée en haut (relecture S34).
209	     Ici la pile et la boîte unique sont deux enfants flex `align-items:center` : la boîte est
210	     centrée sur la pile par construction, quel que soit le nombre de boîtes.
211	     L'accolade `.brace` groupe la pile et matérialise la fusion des N branches en une flèche. */
212	  .converge, .split { display:flex; align-items:center; gap:1.1vw; width:100%; }
213	  .stack { display:flex; flex-direction:column; gap:1.1vh; flex:1 1 0; align-self:stretch; }
214	  .stack .node { flex:1 1 0; }
215	  .merge { display:flex; align-items:center; gap:.7vw; align-self:stretch; flex:0 0 auto; }
216	  .merge .brace { align-self:stretch; width:1.3vw; border:3px solid var(--border); border-left:none; border-radius:0 16px 16px 0; }
217	  .merge .tip { display:flex; flex-direction:column; align-items:center; gap:.5vh; }
218	  .converge > .node, .split > .node { flex:1.15 1 0; }
219	  /* split : l'accolade s'ouvre vers les sorties, donc elle se retourne */
220	  .split .merge .brace { border:3px solid var(--border); border-right:none; border-radius:16px 0 0 16px; order:2; }
221	  .split .merge .tip { order:1; }
222	  /* ====== slide-type: timeline (§5.7) - jalons datés sur un rail ======
223	     Un segment `.dormant` (rail pointillé, pastille creuse) rend visible une période
224	     SANS événement : c'est le vide qui porte le sens, pas les jalons. */
225	  .timeline { display:grid; grid-auto-flow:column; grid-auto-columns:1fr; align-items:start; width:100%; }
226	  .timeline .stage { position:relative; display:flex; flex-direction:column; align-items:center; gap:.8vh; padding:6vh 1vw 0; text-align:center; }
227	  .timeline .stage::before { content:''; position:absolute; top:2.6vh; left:0; right:0; height:3px; background:var(--border); }
228	  .timeline .stage:first-child::before { left:50%; }
229	  .timeline .stage:last-child::before { right:50%; }
230	  .timeline .stage::after { content:''; position:absolute; top:1.7vh; left:50%; margin-left:-8px; width:16px; height:16px; border-radius:50%; background:var(--accent); }
231	  .timeline .stage.dormant::before { background:repeating-linear-gradient(to right, var(--border) 0 9px, var(--bg) 9px 18px); }
232	  .timeline .stage.dormant::after { background:var(--bg); border:3px solid var(--border); }
233	  .timeline .dt { font-family:var(--font-mono); font-size:clamp(11px,1.2vw,19px); font-weight:700; letter-spacing:1px; color:var(--warning); }
234	  .timeline .nm { font-size:clamp(15px,1.8vw,28px); font-weight:700; color:var(--indigo); line-height:1.25; }
235	  .timeline .ex { font-size:clamp(12px,1.25vw,19px); color:var(--muted); line-height:1.3; }
236	  /* ====== slide-type: wrap (§5.7) - un cadre nommé englobe N piliers ======
237	     Le cadre EST le propos (ici : le harness). `.pillar.gap` = pilier non outillé,
238	     bordure pointillée : le manque se montre, il ne se raconte pas. */
239	  .wrap { position:relative; width:100%; margin-top:1.4vh; border:3px solid var(--accent); border-radius:18px; padding:4.4vh 2vw 2.6vh; }
240	  .wrap > .cap { position:absolute; top:0; left:2vw; transform:translateY(-50%); background:var(--bg); padding:0 .8vw; font-family:var(--font-mono); font-size:clamp(11px,1.2vw,19px); font-weight:700; letter-spacing:2px; text-transform:uppercase; color:var(--warning); }
241	  .wrap .pillars { display:grid; grid-template-columns:1fr 1fr; gap:1.4vh 1.6vw; }
242	  .pillar { background:var(--surface); border:1px solid var(--border); border-radius:14px; padding:1.5vh 1.3vw; display:flex; flex-direction:column; gap:.35vh; }
243	  .pillar.gap { border-style:dashed; background:none; }
244	  .pillar .pn { font-size:clamp(16px,1.9vw,30px); font-weight:700; color:var(--indigo); }
245	  .pillar .px { font-size:clamp(12px,1.3vw,20px); color:var(--muted); line-height:1.3; }
246	  /* ====== slide-type: cycle (§5.7) - une boucle : N étapes puis un retour nommé ======
247	     Le retour est la primitive, pas la décoration : il dit ce qui revient, et où. */
248	  .cycle { display:flex; flex-direction:column; gap:1.2vh; width:100%; }
249	  .cycle .ring { display:flex; align-items:stretch; gap:1vw; }
250	  .cycle .ring .node { flex:1 1 0; }
251	  .cycle .ring .arrow { display:flex; align-items:center; font-size:clamp(24px,3vw,46px); color:var(--accent); font-weight:800; }
252	  .cycle .back { display:flex; align-items:center; gap:.9vw; }
253	  .cycle .back .line { position:relative; flex:1 1 0; height:3px; background:var(--border); }
254	  .cycle .back .line::before { content:'◀'; position:absolute; left:-.1em; top:50%; transform:translateY(-50%); color:var(--accent); font-size:clamp(14px,1.6vw,24px); line-height:1; }
255	  .cycle .back .lab { font-size:clamp(13px,1.45vw,22px); color:var(--muted); }
256	  .cycle .back .lab b { color:var(--indigo); font-weight:700; }
257	  /* ====== slide-type: track (§5.7) - un pipeline + le curseur de qui décide ======
258	     Chaque colonne porte une étape et, optionnellement, un `.pin` aligné dessous. */
259	  .track { display:flex; align-items:flex-start; gap:.6vw; width:100%; }
260	  .track .col { flex:1 1 0; display:flex; flex-direction:column; align-items:center; gap:1vh; }
261	  .track .col .step { width:100%; text-align:center; background:var(--surface); border:1px solid var(--border); border-radius:12px; padding:1.2vh .6vw; font-size:clamp(13px,1.55vw,26px); font-weight:700; color:var(--indigo); }
262	  .track .col.here .step { background:var(--accent-soft); border-color:var(--accent); }
263	  .track .arr { flex:0 0 auto; padding-top:1.4vh; font-size:clamp(16px,2vw,32px); color:var(--accent); font-weight:800; }
264	  .track .pin { position:relative; padding-top:2.8vh; font-family:var(--font-mono); font-size:clamp(11px,1.2vw,18px); font-weight:700; color:var(--warning); text-align:center; line-height:1.3; }
265	  .track .pin::before { content:'▲'; position:absolute; top:.2vh; left:50%; transform:translateX(-50%); color:var(--accent); font-size:.9em; }
266	  /* ====== slide-type: links (§5.7) - barre de liens cliquables en pied de slide ======
267	     Le deck se joue en direct : on navigue vers la source devant l'audience. Un lien par source
268	     citée dans la slide, jamais plus de 5. Masqué au gate QA (?slide=N). */
269	  .links { position:absolute; left:9vw; right:9vw; bottom:2.8vh; display:flex; flex-wrap:wrap; gap:.7vh .7vw; align-items:center; }
270	  .links a { font-family:var(--font-mono); font-size:clamp(10px,1.05vw,15px); font-weight:500; color:var(--indigo); text-decoration:none; background:var(--surface); border:1px solid var(--border); border-radius:7px; padding:.5vh .7vw; white-space:nowrap; }
271	  .links a:hover { border-color:var(--accent); }
272	  /* ====== sponsor / mention tierce (encart discret, texte indigo sur surface) ====== */
273	  .sponsor { display:inline-flex; align-items:center; gap:.9vw; align-self:flex-start; background:var(--surface); border:1px solid var(--border); border-radius:12px; padding:1.1vh 1.3vw; }
274	  .sponsor .mark { font-weight:800; font-size:clamp(16px,1.9vw,30px); letter-spacing:-.5px; color:var(--indigo); }
275	  .sponsor .cap { font-family:var(--font-mono); font-size:clamp(11px,1.2vw,18px); font-weight:700; letter-spacing:1px; text-transform:uppercase; color:var(--warning); }
276	  /* ====== identité + chrome de navigation ====== */
277	  /* chrome regroupé en bas à droite : le bas-gauche appartient à la barre de liens (§5.7) */
278	  .chrome { position:fixed; bottom:3vh; right:4vw; display:flex; gap:1.2vw; align-items:baseline; font-family:var(--font-mono); font-size:clamp(11px,1.1vw,16px); color:var(--muted); }
279	  body.capture .chrome, body.capture .links { display:none; } /* gate QA : ?slide=N masque le chrome */
280	  /* ====== mode pointeur (présentation) ======
281	     Le clic cesse de naviguer : on peut désigner et souligner à la souris sans changer de slide.
282	     Ambre décoratif (§1.2 : jamais du texte), donc conforme en tant que marqueur. */
283	  body.laser { cursor:none; }
284	  .laser-dot { position:fixed; z-index:9; width:18px; height:18px; margin:-9px 0 0 -9px; border-radius:50%; background:var(--accent); box-shadow:0 0 0 6px var(--color-glow-soft), 0 0 18px 4px var(--color-glow); pointer-events:none; display:none; }
285	  /* taille CSS explicite : un canvas est un élément remplacé, `inset:0` seul le laisserait
286	     à sa taille intrinsèque (buffer = viewport x devicePixelRatio), donc trace décalée en HiDPI */
287	  .ink { position:fixed; left:0; top:0; width:100vw; height:100vh; z-index:8; pointer-events:none; display:none; }
288	  body.laser .laser-dot, body.laser .ink { display:block; }
289	  .hint b { color:var(--warning); font-weight:700; }
290	</style>
