590	<script>
591	  const slides=[...document.querySelectorAll('.slide')];
592	  const counter=document.querySelector('.counter');
593	  let i=0;
594	  function show(n){
595	    i=Math.max(0,Math.min(slides.length-1,n));
596	    slides.forEach((s,k)=>s.classList.toggle('active',k===i));
597	    counter.textContent=(i+1)+' / '+slides.length;
598	  }
599	  // Gate QA : ?slide=N affiche la slide N seule, chrome masqué (capture PNG propre).
600	  const q=new URLSearchParams(location.search).get('slide');
601	  if(q!==null){ document.body.classList.add('capture'); show(parseInt(q,10)-1); }
602	  else { show(0); }
603	  // Mode pointeur (touche l) : le clic cesse de naviguer, le curseur devient un marqueur ambre,
604	  // et maintenir le bouton trace un trait qui s'efface en ~1,2 s. Sortie par l ou Échap.
605	  const dot=document.querySelector('.laser-dot');
606	  const ink=document.querySelector('.ink');
607	  const ctx=ink.getContext('2d');
608	  const hint=document.querySelector('.hint');
609	  const HINT_NAV='← → naviguer · f plein écran · l pointeur';
610	  const HINT_LASER='<b>pointeur</b> · clic pour souligner · l ou Échap pour sortir';
611	  let laser=false, drawing=false, prev=null;
612	  function sizeInk(){
613	    const r=window.devicePixelRatio||1;
614	    ink.width=innerWidth*r; ink.height=innerHeight*r;
615	    ctx.setTransform(r,0,0,r,0,0);
616	    ctx.lineCap='round'; ctx.lineJoin='round'; ctx.lineWidth=5;
617	    ctx.strokeStyle=getComputedStyle(document.documentElement).getPropertyValue('--accent').trim();
618	  }
619	  function fade(){
620	    if(!laser) return;
621	    ctx.save();
622	    ctx.globalCompositeOperation='destination-out';
623	    // Sous destination-out le compositeur ne lit que l'alpha : le RGB est ignore, aucun pixel noir
624	    // n'est produit. C'est un effaceur a 6% par image, pas une couleur.
625	    ctx.fillStyle='rgba(0,0,0,0.06)'; // brand-exempt: alpha seul lu par destination-out, le RGB n'est jamais peint
626	    ctx.fillRect(0,0,innerWidth,innerHeight);
627	    ctx.restore();
628	    requestAnimationFrame(fade);
629	  }
630	  function setLaser(on){
631	    laser=on; drawing=false; prev=null;
632	    document.body.classList.toggle('laser',on);
633	    hint.innerHTML=on?HINT_LASER:HINT_NAV;
634	    if(on){ sizeInk(); requestAnimationFrame(fade); }
635	    else { ctx.clearRect(0,0,innerWidth,innerHeight); }
636	  }
637	  addEventListener('resize',()=>{ if(laser) sizeInk(); });
638	  document.addEventListener('mousemove',e=>{
639	    if(!laser) return;
640	    dot.style.left=e.clientX+'px'; dot.style.top=e.clientY+'px';
641	    if(drawing){
642	      if(prev){ ctx.beginPath(); ctx.moveTo(prev.x,prev.y); ctx.lineTo(e.clientX,e.clientY); ctx.stroke(); }
643	      prev={x:e.clientX,y:e.clientY};
644	    }
645	  });
646	  document.addEventListener('mousedown',e=>{ if(laser){ drawing=true; prev={x:e.clientX,y:e.clientY}; } });
647	  document.addEventListener('mouseup',()=>{ drawing=false; prev=null; });
648	  document.addEventListener('keydown',e=>{
649	    if(['ArrowRight',' ','PageDown'].includes(e.key)){e.preventDefault();show(i+1);}
650	    else if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();show(i-1);}
651	    else if(e.key==='f'){if(!document.fullscreenElement)document.documentElement.requestFullscreen?.();else document.exitFullscreen?.();}
652	    else if(e.key==='l'){setLaser(!laser);}
653	    else if(e.key==='Escape'&&laser){setLaser(false);}
654	  });
655	  document.addEventListener('click',e=>{ if(laser) return; show(i + (e.clientX < window.innerWidth*0.25 ? -1 : 1));});
656	</script>
